Set<String> selfHostedPins() {
  final yaml = loadWorkflow();
  final pins = <String>{};
  for (final entry in (yaml['jobs'] as Map).entries) {
    final steps = (entry.value as Map)['steps'] as List? ?? const [];
    for (final step in steps) {
      final uses = (step as Map)['uses'];
